#include <bits/stdc++.h>
using namespace std;

class NumArray {
public:
    vector<int> prefix;

    NumArray(vector<int>& nums) {
        int n = (int)nums.size();
        prefix.assign(n + 1, 0);                                          // one extra slot: prefix[0] represents an empty range
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];                               // build the running total in a single pass
        }
    }

    int sumRange(int left, int right) {
        return prefix[right + 1] - prefix[left];                              // O(1): one subtraction, no loop at all
    }
};

int main() {
    vector<int> nums = {-2, 0, 3, -5, 2, -1};
    NumArray numArray(nums);
    cout << numArray.sumRange(0, 2) << endl;
    cout << numArray.sumRange(2, 5) << endl;
    cout << numArray.sumRange(0, 5) << endl;
    return 0;
